INSERT INTO public.game_catalog (id, game_key, name, short_name, tagline, description, instructions, category, difficulty, min_players, max_players, player_modes, estimated_duration, logo_url, cover_image_url, preview_image_url, icon, accent_color, route, status, is_active, is_featured, sort_order, rules, config, created_at, updated_at) VALUES ('862ca507-de35-44cc-ba61-b16a72b2f5d0', 'meme-battle', 'Meme Battle', 'Meme Battle', 'En komik meme kazanır.', 'Oyuncular verilen duruma en uygun meme veya açıklamayı seçer. Diğer oyuncuların oylarıyla turun kazananı belirlenir.', 'Her tur bir durum gösterilir. Elindeki seçeneklerden en komik olanı seç. Diğer oyuncular oy verdikten sonra puanlar açıklanır.', 'party', 'easy', 3, 10, '["multiplayer", "group"]', 10, NULL, NULL, NULL, 'laugh', '#f97316', '/games/meme-battle', 'draft', false, true, 1, '{"voting": true, "roundBased": true}', '{"rounds": 5, "timerSeconds": 30}', '2026-10-30 02:26:07.759378+01', '2026-10-30 02:26:07.759378+01');
INSERT INTO public.game_catalog (id, game_key, name, short_name, tagline, description, instructions, category, difficulty, min_players, max_players, player_modes, estimated_duration, logo_url, cover_image_url, preview_image_url, icon, accent_color, route, status, is_active, is_featured, sort_order, rules, config, created_at, updated_at) VALUES ('07054ae0-981d-4cd4-9abe-d4ec8aa7a962', 'number-guess', 'Number Guess', 'Number Guess', 'Rakibinin gizli sayısını bul.', 'Her oyuncu gizli bir sayı belirler. Diğer oyuncular tahmin yapar ve aldıkları ipuçlarıyla doğru sayıyı bulmaya çalışır.', 'Gizli sayıyı belirle. Rakibinin tahminlerine ipucu ver ve kendi tahminlerini kullanarak rakibinin sayısını bul.', 'logic', 'medium', 2, 2, '["multiplayer", "duel"]', 5, NULL, NULL, NULL, 'brain', '#06b6d4', '/games/number-guess', 'draft', false, true, 2, '{"feedback": true, "secretNumber": true}', '{"maxNumber": 100, "minNumber": 1, "attemptLimit": 10}', '2026-10-30 02:26:07.759378+01', '2026-10-30 02:26:07.759378+01');
INSERT INTO public.game_catalog (id, game_key, name, short_name, tagline, description, instructions, category, difficulty, min_players, max_players, player_modes, estimated_duration, logo_url, cover_image_url, preview_image_url, icon, accent_color, route, status, is_active, is_featured, sort_order, rules, config, created_at, updated_at) VALUES ('69a106f5-2f9c-44b2-993a-4fa64e7337ef', 'word-bluff', 'Word Bluff', 'Word Bluff', 'Doğru cevabı bul veya herkesi kandır.', 'Oyuncular bir kelimeye ait gerçek tanımı bulmaya çalışırken diğer oyuncular sahte tanımlar yazar.', 'Sorudaki kelime için kendi tanımını oluştur. Gerçek tanımı bulmaya çalışırken diğer oyuncuları da kandırmayı dene.', 'party', 'medium', 3, 8, '["multiplayer", "group"]', 10, NULL, NULL, NULL, 'messages-square', '#a78bfa', '/games/word-bluff', 'draft', false, false, 3, '{"voting": true, "bluffing": true}', '{"rounds": 5, "timerSeconds": 45}', '2026-10-30 02:26:07.759378+01', '2026-10-30 02:26:07.759378+01');
