INSERT INTO public.game_catalog (id, game_key, name, short_name, tagline, description, instructions, category, difficulty, min_players, max_players, player_modes, estimated_duration, logo_url, cover_image_url, preview_image_url, icon, accent_color, route, status, is_active, is_featured, sort_order, rules, config, created_at, updated_at) VALUES ('a064c794-0280-4309-bd5a-eb3aef3e9b26', 'friend-tier-list', 'Friend Tier List', 'Tier List', 'Arkadaşlarını A''dan E''ye sırala.', 'Oyuncular eğlenceli ve tartışmalı sorulara göre arkadaşlarının fotoğraflarını S, A, B, C, D ve E seviyelerine yerleştirir. Herkesin sıralaması karşılaştırılır.', 'Bir soru gösterilir. Arkadaşlarının fotoğraflarını sürükleyerek tier list sıralarına bırak. Herkes tamamladığında sıralamalar karşılaştırılır.', 'party', 'easy', 2, 10, '["multiplayer", "group"]', 10, NULL, NULL, NULL, 'users', '#e9b949', '/games/friend-tier-list', 'draft', false, false, 20, '{"tiers": ["S", "A", "B", "C", "D", "E"], "voting": false, "photoBased": true, "roundBased": true, "dragAndDrop": true, "tierRanking": true}', '{"rounds": 10, "shufflePlayers": true, "allowCustomQuestions": true, "showResultsAfterRound": true}', '2026-11-10 00:01:06.325821+01', '2026-11-10 00:01:06.325821+01');
