INSERT INTO public.game_catalog (id, game_key, name, short_name, tagline, description, instructions, category, difficulty, min_players, max_players, player_modes, estimated_duration, logo_url, cover_image_url, preview_image_url, icon, accent_color, route, status, is_active, is_featured, sort_order, rules, config, created_at, updated_at) VALUES ('e3a4efed-3d04-42e7-84ea-bdbb0b52c870', 'okey-101', '101 Okey', '101', 'Open with 101. Keep the table moving.', 'Play Turkish 101 Okey with four players, opening melds, table melds and real-time turns.', 'Four players join a room. The first player starts with 22 tiles and others with 21. Draw one tile, open valid runs or groups totalling at least 101 points, then add tiles to table melds and discard. Finish by emptying your hand after opening.', 'tabletop', 'hard', 4, 4, '["multiplayer"]', 35, NULL, NULL, NULL, '🎴', '#d1ad69', '/games/okey101', 'active', true, false, 81, '{"players": 4, "openingPoints": 101, "drawBeforeDiscard": true, "supportsPairsOpening": true}', '{"realtime": true, "roomCode": true}', '2026-11-16 10:16:48.67422+01', '2026-11-16 10:16:48.67422+01');
